**Bot Code:**

Below is a basic example of a bot that uses historical data to make investment recommendations based on certain criteria. This bot will be built using Python and the `yfinance` library to fetch historical stock data and the `pandas` library to analyze it.

```python
import yfinance as yf
import pandas as pd
import numpy as np
import matplotlib.pyplot as plt

class InvestmentBot:
    def __init__(self, stock_list, time_period):
        self.stock_list = stock_list
        self.time_period = time_period
        self.data = {}

    def fetch_data(self):
        for stock in self.stock_list:
            ticker = yf.Ticker(stock)
            hist = ticker.history(period=self.time_period)
            self.data[stock] = hist

    def calculate_returns(self):
        for stock in self.data:
            self.data[stock]['Returns'] = self.data[stock]['Close'].pct_change()

    def calculate_volatility(self):
        for stock in self.data:
            self.data[stock]['Volatility'] = self.data[stock]['Returns'].rolling(window=20).std() * np.sqrt(252)

    def calculate_sharpe_ratio(self):
        for stock in self.data:
            self.data[stock]['Sharpe Ratio'] = (self.data[stock]['Returns'].mean() - 0.05) / self.data[stock]['Volatility']

    def get_recommendations(self):
        recommendations = {}
        for stock in self.data:
            if self.data[stock]['Sharpe Ratio'].iloc[-1] > 0.5:
                recommendations[stock] = self.data[stock]['Sharpe Ratio'].iloc[-1]
        return recommendations

    def plot_recommendations(self):
        plt.figure(figsize=(10, 6))
        for stock in self.data:
            if self.data[stock]['Sharpe Ratio'].iloc[-1] > 0.5:
                plt.plot(self.data[stock]['Returns'], label=stock)
        plt.legend()
        plt.show()

